questScroll = 0;
questMoveSpeed = 0;
questX = 0;
cf = 2;
maxScroll = 8;
onEnterFrame = function()
{
   if(Key.isDown(37) || Key.isDown(65))
   {
      questMoveSpeed += 2;
   }
   if(Key.isDown(39) || Key.isDown(68))
   {
      questMoveSpeed -= 2;
   }
   questMoveSpeed *= 0.9;
   if(questScroll <= 0 && questMoveSpeed > 0)
   {
      questScroll = 0;
      questMoveSpeed = 0;
      questX = 0;
      cf = 2;
   }
   if(questScroll >= maxScroll && questX <= 0 && questMoveSpeed < 0)
   {
      questScroll = maxScroll;
      questMoveSpeed = 0;
      questX = 0;
      cf = 2;
   }
   questX += Math.round(questMoveSpeed);
   if(questX > 50 && questScroll > 0)
   {
      questScroll -= 1;
      questX -= 50;
      cf = 2;
   }
   if(questX < 0 && questScroll < maxScroll)
   {
      questScroll += 1;
      questX += 50;
      cf = 2;
   }
   cf -= 1;
};

onClipEvent(enterFrame){
   if(_parent.questScroll > 0)
   {
      targetAlpha = 100;
   }
   else
   {
      targetAlpha = 0;
   }
   _alpha = _alpha + Math.round((targetAlpha - _alpha) / 2);
}

onClipEvent(enterFrame){
   if(_parent.questScroll < _parent.maxScroll)
   {
      targetAlpha = 100;
   }
   else
   {
      targetAlpha = 0;
   }
   _alpha = _alpha + Math.round((targetAlpha - _alpha) / 2);
}

ind = Math.round((_X - 15) / 210) * 8 + Math.round(_Y / 55);
if(_parent._currentframe == 38)
{
   ind += 24;
}
trueInd = _root.save.arenaEvent * 100 + ind;
pointText.text = _root.withComma(_parent.rewardArray[ind]);
if(ind == 32)
{
   if(_root.systemtimenow < _root.eventEndTime[_root.save.arenaEvent] || _parent.rewardArray[ind] >= 1000000)
   {
      pointText.text = "???,???";
   }
}
prizeType = _parent.rewardTypeArray[ind];
prizeIn.gotoAndStop(prizeType);
if(_root.save.arenaEventReward[trueInd] == true)
{
   ol.gotoAndStop(3);
