      ol.gotoAndStop(7);
   }
}
else if(_root.save.arenaEventPoint[_root.save.arenaEvent] >= _parent.rewardArray[ind])
{
   ol.gotoAndStop(2);
   if(ind == 32)
   {
      ol.gotoAndStop(6);
