}
onRelease = function()
{
   if(_root.save.arenaEventPoint[_root.save.arenaEvent] >= _parent.rewardArray[ind] && _root.save.arenaEventReward[trueInd] != true && pointText.text != "???,???")
   {
      if(prizeType <= 13 || prizeType >= 20)
      {
         if(prizeType == 1)
