         {
            _root.save.mysteryBox[5] += 1000;
         }
         else if(prizeType == 10)
         {
            _root.save.mysteryBox[5] += 3000;
         }
         else if(prizeType == 11)
         {
            _root.save.mysteryBox[5] += 6000;
         }
         else if(prizeType == 12)
         {
            _root.save.botPill += 1;
