      remaining -= elapsed_minutes * 60;
      elapsed_seconds = Math.floor(remaining / 1);
      remaining -= elapsed_seconds * 1;
      if(elapsed_hours < 10)
      {
         elapsed_hours = "0" + elapsed_hours;
      }
      if(elapsed_minutes < 10)
