            {
               _root.dispNews(18,"Tree planted! (-" + _root.withComma(coinCost) + " Coins)");
            }
            else if(gardenPointCost > 0)
            {
               _root.dispNews(18,"Tree planted! (-" + _root.withComma(gardenPointCost) + " Garden Points)");
