         _root.save.gardenBreed1 = _root.breedSeed1;
         _root.save.gardenBreed2 = ID;
         _root.save.gardenBreedResearch = 0;
         _parent.gotoAndStop(2);
      }
   }
   _root.actiondescription = "";
};

