      {
         coolDown = 60;
         _root.arenaDelay = skillDelay;
         _root.arenaDelay2 = skillDelay;
         _root.save.arenaSpirit += mpToRefill;
         _root.save.arenaPixel -= pixelCost;
      }
   }
}

