function checkUpgrade()
   {
      runeLevel = _root.save.arenaRuneLevel[runeID];
      if(runeLevel < 100)
      {
         fragCost = (runeLevel + 1) * (runeLevel + 1) * 1000 - 1;
         scmCost = (runeLevel + 1) * (runeLevel + 1) * 5;
         unobCost = (runeLevel + 1) * (runeLevel + 1) * 1;
         if(runeLevel >= 50)
         {
            scmCost *= 2;
            unobCost *= 2;
         }
         if(runeLevel % 10 == 9)
         {
            scmCost *= 5;
            unobCost *= 5;
         }
      }
      else
      {
         fragCost = Infinity;
         scmCost = Infinity;
         unobCost = Infinity;
      }
      if(_root.save.arenaEnhancerFragment >= fragCost && _root.save.arenaSuperiorCraft >= scmCost && _root.save.arenaUnobtainium >= unobCost)
      {
         _alpha = 100;
      }
      else
      {
         _alpha = 30;
      }
   }

