function checkFrame()
   {
      if(_parent.type == "Weapon")
      {
         gotoAndStop(2);
      }
      else if(_parent.subtype == "Hat")
      {
         gotoAndStop(3);
      }
      else if(_parent.subtype == "Shirt")
      {
         gotoAndStop(4);
      }
      else if(_parent.subtype == "Gloves")
