   this["mmrJudgement" + judgementInst]._x = notePositionArr[noteNum] * 50;
   this["mmrJudgement" + judgementInst].pgm.gotoAndStop(pgm);
   this["mmrJudgement" + judgementInst].earlyLate.gotoAndStop(earlyLate);
   if(comboCount > 0)
