function calcRating(gameID, scr, ran)
{
   rat = 0;
   if(gameID == 1)
   {
      thresh = 4200000;
      crv = 2;
      nob = 0.3;
   }
   else if(gameID == 2)
   {
      thresh = 1750000;
      crv = 0.75;
      nob = 0.45;
   }
   else if(gameID == 3)
   {
      thresh = 2400000;
      crv = 2;
      nob = 0.45;
   }
   else if(gameID == 4)
   {
      thresh = 3300000;
      crv = 3.5;
      nob = 0.9;
   }
   else if(gameID == 5)
   {
      thresh = 10000000;
      crv = 1.25;
      nob = 0.3;
   }
   else if(gameID == 6)
   {
      thresh = 6000000;
      crv = 2.5;
      nob = 0.45;
   }
   else if(gameID == 7)
   {
      thresh = 13500000;
      crv = 1;
      nob = 0.3;
   }
   else if(gameID == 8)
   {
      thresh = 6000000;
      crv = 1.25;
      nob = 0.3;
   }
   if(scr > thresh)
   {
      scr = Math.floor(thresh + (scr - thresh) * crv);
   }
   thresh *= 0.7;
   mul = 0;
   if(ran == 1)
   {
      mul = 1.4;
   }
   else if(ran == 2)
   {
      mul = 0.5;
   }
   else if(ran == 3)
   {
      mul = 0.1;
   }
   if(scr > thresh * 1.6)
   {
      rat = Math.floor((150 + (scr - thresh * 1.6) / (thresh * 0.05)) * mul);
   }
   else if(scr > thresh)
   {
      rat = Math.floor((120 + (scr - thresh) / (thresh * 0.02)) * mul);
   }
   else
   {
      rat = Math.floor(Math.pow(scr / thresh,nob) * 120 * mul);
   }
   if(isNaN(rat))
   {
      rat = 0;
   }
   if(rat > 200)
   {
      rat = 200;
   }
   return rat;
}

