function ratingToString(rat)
{
   if(rat < 10)
   {
      res = "0.0" + Math.floor(rat);
   }
   else if(rat < 100)
   {
      res = "0." + Math.floor(rat);
   }
   else
   {
      res = Math.floor(rat / 100) + "." + Math.floor(rat % 100);
      if(Math.floor(rat % 100) < 10)
      {
         res = Math.floor(rat / 100) + ".0" + Math.floor(rat % 100);
      }
   }
   return res;
}

