            i++;
         }
         stadiumHero.energy -= 10;
         if(stadiumHero.energy < 0)
         {
            stadiumHero.energy = 0;
         }
         this["stadiumEnemy" + user].energy += 40;
      }
      if(itemName == "Slow")
      {
         i = 1;
