         {
            if(i != user)
            {
               this["stadiumEnemy" + i].darkDur = 5;
            }
            i++;
         }
         stadiumHero.darkDur = 5;
      }
      if(itemName != "")
      {
         _parent.breakStadium(this["stadiumEnemy" + user].mehName + " used " + itemName + "!");
