function evalCost(abc)
{
   if(abc == 400)
   {
      return Infinity;
   }
   if(abc >= 300)
   {
      return Math.floor(abc * 8 - 1600);
   }
   if(abc >= 200)
   {
      return Math.floor(abc * 4 - 400);
   }
   if(abc >= 100)
   {
      return Math.floor(abc * 2 - 100);
   }
   return Math.floor(abc);
}

