}

function bSqrt(bn)
{
   tmpB = _root.bGetB(bn);
   tmpE = _root.bGetE(bn);
   if(tmpE % 2 != 0)
   {
      tmpE -= 1;
      tmpB *= 10;
   }
   tmpI = 1;
   while(tmpI <= 4)
   {
      if(tmpE >= 2)
      {
         tmpE -= 2;
         tmpB *= 100;
      }
      else
      {
         tmpI = 5;
      }
      tmpI++;
   }
   tmpE /= 2;
   tmpB = Math.floor(Math.sqrt(tmpB));
   return _root.bCreate(tmpB,tmpE);
}

