function printMoney(moneyToPrintX)
{
   _root.printPercent = 0;
   if(_root.save.printerCharge > 0)
   {
      if(_root.save.questType == "Print")
      {
         if(_root.save.questSubtype == "Any")
         {
            _root.save.questCount += 1;
         }
      }
      _root.save.printerCharge -= 1;
