function toB(reg)
{
   if(reg == Infinity || isNaN(reg))
   {
      return 0;
   }
   tmpB = reg;
   tmpE = 0;
   while(tmpB > 999999999999)
   {
      tmpB = Math.floor(tmpB / 10);
      tmpE += 1;
   }
   tmpB = Math.floor(tmpB);
   return _root.bCreate(tmpB,tmpE);
}

function toFW(str)
{
   str += "";
   str = str.replace("0","０");
   str = str.replace("1","１");
   str = str.replace("2","２");
   str = str.replace("3","３");
   str = str.replace("4","４");
   str = str.replace("5","５");
   str = str.replace("6","６");
   str = str.replace("7","７");
   str = str.replace("8","８");
   str = str.replace("9","９");
   return str;
}

