function tukkunRandom(noZero, maxChance, maxVal)
{
   maxVal = Math.ceil(maxVal);
   if(Math.random() < noZero)
   {
      val = Math.ceil(Math.random() * maxVal);
      if(Math.random() < maxChance)
      {
         val = maxVal;
      }
   }
   else
   {
      val = 0;
   }
}

