function addAchievementR(ID, secret, achName, descA, descB, need, where, amnt)
{
   var _loc1_ = new Object();
   _loc1_.ID = ID;
   _loc1_.secret = secret;
   _loc1_.achName = achName;
   _loc1_.descA = descA;
   _loc1_.descB = descB;
